using Erp.Abstractions.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
namespace Erp.Modules.Sales;

internal static class SalesEndpoints
{
    public static void MapSalesEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var group = endpoints.MapGroup("/api/v1/sales/quotations").WithTags("Sales Quotations"); group.MapGet("/", Search).RequirePermission(SalesPermissions.QuotationRead); group.MapGet("/{id:guid}", Get).RequirePermission(SalesPermissions.QuotationRead); group.MapPost("/", (QuotationRequest request, IQuotationService service, CancellationToken token) => Run(() => service.CreateAsync(request, token), true)).RequirePermission(SalesPermissions.QuotationManage); group.MapPut("/{id:guid}", (Guid id, QuotationRequest request, IQuotationService service, CancellationToken token) => Run(() => service.UpdateAsync(id, request, token))).RequirePermission(SalesPermissions.QuotationManage); foreach (var state in new[] { QuotationState.Sent, QuotationState.Accepted, QuotationState.Rejected, QuotationState.Expired, QuotationState.Cancelled }) { var target = state; group.MapPost($"/{{id:guid}}/{state.ToString().ToLowerInvariant()}", (Guid id, QuotationTransitionRequest request, IQuotationService service, CancellationToken token) => Run(() => service.TransitionAsync(id, target, request.ConcurrencyStamp, token))).RequirePermission(SalesPermissions.QuotationConfirm); }
        group.MapPost("/{id:guid}/archive", (Guid id, QuotationTransitionRequest request, IQuotationService service, CancellationToken token) => Run(() => service.SetArchivedAsync(id, request.ConcurrencyStamp, true, token))).RequirePermission(SalesPermissions.QuotationManage); group.MapPost("/{id:guid}/reactivate", (Guid id, QuotationTransitionRequest request, IQuotationService service, CancellationToken token) => Run(() => service.SetArchivedAsync(id, request.ConcurrencyStamp, false, token))).RequirePermission(SalesPermissions.QuotationManage); group.MapPost("/{id:guid}/convert", (Guid id, ConvertQuotationRequest request, ISalesOrderService service, CancellationToken token) => Run(() => service.ConvertAsync(id, request, token), true)).RequirePermission(SalesPermissions.OrderManage);
        var orders = endpoints.MapGroup("/api/v1/sales/orders").WithTags("Sales Orders"); orders.MapGet("/", (string? search, SalesOrderState? state, string? sort, bool descending, int page, int pageSize, ISalesOrderService service, CancellationToken token) => Run(() => service.SearchAsync(new(search, state, sort ?? "updated", descending, page < 1 ? 1 : page, pageSize < 1 ? 25 : pageSize), token))).RequirePermission(SalesPermissions.OrderRead); orders.MapGet("/{id:guid}", async (Guid id, ISalesOrderService service, CancellationToken token) => await service.GetAsync(id, token) is { } item ? Results.Ok(item) : Results.NotFound()).RequirePermission(SalesPermissions.OrderRead); orders.MapPost("/{id:guid}/confirm", (Guid id, QuotationTransitionRequest request, ISalesOrderService service, CancellationToken token) => Run(() => service.TransitionAsync(id, SalesOrderState.Confirmed, request.ConcurrencyStamp, token))).RequirePermission(SalesPermissions.OrderConfirm); orders.MapPost("/{id:guid}/cancel", (Guid id, QuotationTransitionRequest request, ISalesOrderService service, CancellationToken token) => Run(() => service.TransitionAsync(id, SalesOrderState.Cancelled, request.ConcurrencyStamp, token))).RequirePermission(SalesPermissions.OrderCancel);
    }
    private static Task<IResult> Search(string? search, QuotationState? state, bool includeArchived, string? sort, bool descending, int page, int pageSize, IQuotationService service, CancellationToken token) => Run(() => service.SearchAsync(new(search, state, includeArchived, sort ?? "updated", descending, page < 1 ? 1 : page, pageSize < 1 ? 25 : pageSize), token));
    private static async Task<IResult> Get(Guid id, IQuotationService service, CancellationToken token) => await service.GetAsync(id, token) is { } item ? Results.Ok(item) : Results.NotFound();
    private static async Task<IResult> Run<T>(Func<Task<T>> action, bool created = false) { try { var value = await action(); return created ? Results.Created(value is QuotationDto quotation ? $"/api/v1/sales/quotations/{quotation.Id}" : value is SalesOrderDto order ? $"/api/v1/sales/orders/{order.Id}" : "/api/v1/sales", value) : Results.Ok(value); } catch (SalesValidationException ex) { return Results.ValidationProblem(ex.Errors); } catch (SalesConcurrencyException ex) { return Results.Conflict(new { error = ex.Message }); } catch (KeyNotFoundException) { return Results.NotFound(); } }
}
